package Day4;

public class IF_ELSE_IF_conditon {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
//check num is +ve, -ve,zero
		int num=-34;
		if(num>0)
		{
			System.out.println("Number is positive");
		}
		else if(num<0)
		{
			System.out.println("Number is negaitive");
		}
		else
		{
			System.out.println("Number is zero");
		}
	}

}
